themes.css:
:root {
	/* Surfaces at hue 258 with 38-50% saturation. Below ~40% sat at low
	   lightness reads as nearly-neutral grey; 42-50% is what makes the
	   violet actually perceivable. The previous 28% pass looked like
	   the same grey palette to the eye. */
	--background-primary: hsl(258, 45%, 12%);
	--background-secondary: hsl(258, 42%, 16%);
	--background-secondary-alt: hsl(258, 45%, 14%);
	--background-tertiary: hsl(258, 50%, 7%);
	--background-textarea: hsl(258, 38%, 21%);
	--background-header-primary: hsl(258, 42%, 16%);
	--background-header-primary-hover: hsl(258, 42%, 19%);
	--background-header-secondary: hsl(258, 45%, 12%);
	/* Modifier overlays — brand-tinted hsla, low alpha. */
	--background-modifier-hover: hsla(258, 55%, 72%, 0.10);
	--background-modifier-selected: hsla(258, 65%, 72%, 0.20);
	--background-modifier-accent: hsla(258, 35%, 60%, 0.10);
	/* Brand */
	--brand-primary: #a98cf5;
	--brand-secondary: #8b6ddf;
	--brand-primary-light: #c0a8ff;
	--brand-primary-fill: #ffffff;
	--text-on-brand-primary: #ffffff;
	/* Text */
	--text-primary: #e4e4f7;
	--text-secondary: #b8b3d4;
	--text-tertiary: #8b86a8;
	--text-primary-muted: #b8b3d4;
	--text-link: #c0a8ff;
	/* Border — visibly violet, one step above lightest surface. */
	--border-color: hsl(258, 35%, 26%);
}

:root {
	/* Surfaces at hue 35 with bumped saturation — same reason as the
	   violet theme: low sat at low lightness reads as grey, not amber. */
	--background-primary: hsl(35, 35%, 11%);
	--background-secondary: hsl(35, 32%, 15%);
	--background-secondary-alt: hsl(35, 35%, 13%);
	--background-tertiary: hsl(35, 40%, 7%);
	--background-textarea: hsl(35, 30%, 19%);
	--background-header-primary: hsl(35, 32%, 15%);
	--background-header-primary-hover: hsl(35, 35%, 18%);
	--background-header-secondary: hsl(35, 35%, 11%);
	/* Modifier overlays at the amber hue. */
	--background-modifier-hover: hsla(35, 65%, 68%, 0.10);
	--background-modifier-selected: hsla(35, 75%, 68%, 0.20);
	--background-modifier-accent: hsla(35, 45%, 60%, 0.10);
	/* Brand */
	--brand-primary: #f5b366;
	--brand-secondary: #d99850;
	--brand-primary-light: #f8c585;
	--brand-primary-fill: #1c1814;
	--text-on-brand-primary: #1c1814;
	/* Text */
	--text-primary: #ebe1d4;
	--text-secondary: #c8bba9;
	--text-tertiary: #968a7a;
	--text-primary-muted: #c8bba9;
	--text-link: #f8c585;
	/* Border */
	--border-color: hsl(35, 30%, 24%);
}
